import {useEffect,useLayoutEffect,useRef,type ComponentRef} from "react";
import {Platform,Text,View,type ViewProps} from "react-native";
import {createStore,type StoreApi} from "zustand/vanilla";
import {useStore} from "zustand";
import {Select} from "@/components/nyc-tron/ui/components/Select";
import {Button} from "@/components/nyc-tron/ui/components/Button";
import {UnitInput} from "@/components/nyc-tron/ui/components/shell/UnitInput";
import {PanResponderDrag} from "@/components/nyc-tron/ui/components/gestures/PanResponderDrag";
import type {DragTransport,DragPoint} from "@/components/nyc-tron/ui/components/gestures/drag-transport";
import {keyboardKey} from "@/components/nyc-tron/ui/components/gestures/drag-transport";
import {LinePiece} from "@/components/nyc-tron/ui/components/forge/vector/vector-controls";
import {joinClasses} from "@/components/nyc-tron/ui/components/styles";
import {bounded,validateCurve,moveCurvePoint,evaluateCurve,type ColorCurve} from "@/components/nyc-tron/ui/components/forge/color/color-adjustments";
export type {ColorCurve,CurvePoint} from "@/components/nyc-tron/ui/components/forge/color/color-adjustments";
/** One controlled channel curve and its document revision boundary. */
export interface CurvesEditorProps extends Omit<ViewProps,"children">{
 readonly scope:string;
 readonly value:ColorCurve;
 readonly selectedId:string;
 readonly onSelect:(id:string)=>void;
 readonly onPreview?:(value:ColorCurve|undefined)=>void;
 readonly onCommit:(value:ColorCurve,selectedId:string)=>void;
 /** Stable IDs are allocated by the host, not inferred from point coordinates. */
 readonly createPointId:()=>string;
 /** Application-specific curve presets; an identity reset is always available. */
 readonly presets?:readonly {readonly id:string;readonly label:string;readonly curve:ColorCurve}[];
 /** Optional multi-channel selector; all three fields are required together. */
 readonly channelSelection?:{readonly channels:readonly {readonly id:string;readonly label:string}[];readonly value:string;readonly onChange:(id:string)=>void};
 readonly height?:number;readonly disabled?:boolean;readonly unstyled?:boolean;
 /** Native consumers with GestureHandlerRootView can supply GestureHandlerDrag. */
 readonly transport?:DragTransport;
}
type Geometry={x:number;y:number;width:number;height:number};
type Local={width:number;preview:ColorCurve|null};
/** Editable normalized transfer curve with pointer preview, single release commit and keyboard/numeric alternatives. */
export function CurvesEditor({scope,value,selectedId,onSelect,onPreview,onCommit,createPointId,presets=[],channelSelection,height=200,disabled=false,unstyled=false,transport:Transport=PanResponderDrag,...props}:CurvesEditorProps){
 validateCurve(value);
 if(presets.length>128||new Set(presets.map(p=>p.id)).size!==presets.length||presets.some(p=>!p.id||!p.label))throw new TypeError('Curve presets require at most 128 distinct labeled IDs');presets.forEach(p=>validateCurve(p.curve));
 if(channelSelection&&(!channelSelection.channels.some(c=>c.id===channelSelection.value)||new Set(channelSelection.channels.map(c=>c.id)).size!==channelSelection.channels.length||channelSelection.channels.length>16))throw new TypeError('Choose a distinct available curve channel');
 bounded(height,88,600,'Curve height');
 const selected=value.points.find(p=>p.id===selectedId);if(!selected)throw new TypeError('Selected curve point is unavailable');
 const local=useRef<StoreApi<Local>|null>(null);local.current??=createStore<Local>(()=>({width:0,preview:null}));const store=local.current,state=useStore(store,s=>s);
 const root=useRef<ComponentRef<typeof View>|null>(null),geometry=useRef<Geometry|null>(null);
 const drag=useRef<{scope:string;start:ColorCurve;id:string;next:ColorCurve}|null>(null);
 const callbacks=useRef({onPreview,onCommit});callbacks.current={onPreview,onCommit};
 const pending=useRef<{scope:string;start:DragPoint;latest:DragPoint}|null>(null);
 const cancel=()=>{pending.current=null;if(!drag.current)return;drag.current=null;store.setState({preview:null});callbacks.current.onPreview?.(undefined);};
 useLayoutEffect(()=>{cancel();return cancel;},[scope,disabled]);
 useEffect(()=>()=>cancel(),[]);
 const measure=()=>{root.current?.measureInWindow((x,y,width,measuredHeight)=>{if([x,y,width,measuredHeight].every(Number.isFinite)&&width>44&&measuredHeight>44){geometry.current={x,y,width,height:measuredHeight};store.setState({width});}});};
 const adjust=(point:DragPoint)=>{
  const current=drag.current,g=geometry.current;if(!current||!g||disabled||current.scope!==scope)return;
  const x=Math.max(0,Math.min(1,(point.x-g.x-22)/(g.width-44))),y=Math.max(0,Math.min(1,1-(point.y-g.y-22)/(g.height-44)));
  current.next=moveCurvePoint(current.start,current.id,x,y);store.setState({preview:current.next});onPreview?.(current.next);
 };
 const begin=(point:DragPoint)=>{
  if(disabled)return;
  const request={scope,start:point,latest:point};pending.current=request;
  root.current?.measureInWindow((x,y,width,measuredHeight)=>{
   if(pending.current!==request)return;
   pending.current=null;
   if(![x,y,width,measuredHeight].every(Number.isFinite)||width<=44||measuredHeight<=44)return;
   const g={x,y,width,height:measuredHeight};geometry.current=g;store.setState({width});
   const ordered=value.points.map(p=>({p,d:Math.hypot(g.x+22+p.x*(g.width-44)-request.start.x,g.y+22+(1-p.y)*(g.height-44)-request.start.y)})).sort((a,b)=>a.d-b.d);
   const hit=ordered[0];if(!hit||hit.d>44)return;onSelect(hit.p.id);drag.current={scope,start:value,id:hit.p.id,next:value};adjust(request.latest);
  });
 };
 const commitPoint=(x:number,y:number)=>{if(disabled)return;onCommit(moveCurvePoint(value,selectedId,x,y),selectedId);};
 const keyDown=(event:unknown)=>{const key=keyboardKey(event as Parameters<typeof keyboardKey>[0]);if(key==='Escape'){cancel();return;}if(disabled)return;const d=.01;let x=selected.x,y=selected.y;if(key==='ArrowLeft')x-=d;else if(key==='ArrowRight')x+=d;else if(key==='ArrowUp')y+=d;else if(key==='ArrowDown')y-=d;else return;(event as {preventDefault?:()=>void}).preventDefault?.();commitPoint(Math.max(0,Math.min(1,x)),Math.max(0,Math.min(1,y)));};
 const shown=state.preview??value,width=Math.max(88,state.width||240),w=width-44,h=height-44;
 const samples=Array.from({length:129},(_,i)=>({x:22+i/128*w,y:22+(1-evaluateCurve(shown,i/128))*h}));
 const index=value.points.indexOf(selected),canRemove=index>0&&index<value.points.length-1;
 return <View {...props} style={[{gap:8},props.style]}>
  {channelSelection?<Select label="Curve channel" value={channelSelection.value} options={channelSelection.channels.map(c=>({value:c.id,label:c.label}))} disabled={disabled} unstyled={unstyled} onValueChange={channelSelection.onChange}/>:null}
  {presets.length?<Select label="Curve preset" value="" placeholder="Apply a curve preset" options={presets.map(p=>({value:p.id,label:p.label}))} disabled={disabled} unstyled={unstyled} onValueChange={id=>{const preset=presets.find(p=>p.id===id);if(!disabled&&preset)onCommit(preset.curve,preset.curve.points[0]!.id);}}/>:null}
  <Button title="Reset curve to identity" disabled={disabled} unstyled={unstyled} onPress={()=>{if(!disabled){const points=[{...value.points[0]!,x:0,y:0},{...value.points.at(-1)!,x:1,y:1}];onCommit({...value,points},points[0]!.id);}}}/>
  <Select label="Curve interpolation" value={value.interpolation} options={[{value:'linear',label:'Linear'},{value:'monotone',label:'Monotone cubic'}]} disabled={disabled} unstyled={unstyled} onValueChange={interpolation=>{if(!disabled)onCommit({...value,interpolation:interpolation as ColorCurve['interpolation']},selectedId);}}/>
  <Select label="Curve control point" value={selectedId} options={value.points.map((p,i)=>({value:p.id,label:`Point ${i+1}: input ${p.x.toFixed(3)}, output ${p.y.toFixed(3)}`}))} disabled={disabled} unstyled={unstyled} onValueChange={onSelect}/>
  <Transport disabled={disabled} onBegin={begin} onMove={(point,touches)=>{if(touches!==1){cancel();return;}if(pending.current)pending.current.latest=point;else adjust(point);}} onCancel={cancel} onRelease={point=>{
   pending.current=null;adjust(point);const current=drag.current;drag.current=null;store.setState({preview:null});onPreview?.(undefined);if(!disabled&&current&&current.scope===scope&&current.next.points.some((p,i)=>p.x!==current.start.points[i]!.x||p.y!==current.start.points[i]!.y))onCommit(current.next,current.id);
  }}><View ref={root} collapsable={false} onLayout={measure} accessible accessibilityRole="adjustable" accessibilityLabel="Curve point output" aria-valuemin={0} aria-valuemax={1} aria-valuenow={selected.y} aria-valuetext={`Input ${selected.x}, output ${selected.y}`} aria-disabled={disabled}
   accessibilityActions={[{name:'increment',label:'Increase output'},{name:'decrement',label:'Decrease output'}]} onAccessibilityAction={e=>{if(e.nativeEvent.actionName==='increment')commitPoint(selected.x,Math.min(1,selected.y+.01));if(e.nativeEvent.actionName==='decrement')commitPoint(selected.x,Math.max(0,selected.y-.01));}}
   {...{focusable:!disabled,onKeyDown:keyDown,onPointerEnter:measure,className:joinClasses(!unstyled&&'border border-border rounded-control bg-surface-sunken focus-visible:ring-2 focus-visible:ring-focus')}}
   style={{height,overflow:'hidden',...(Platform.OS==='web'?{userSelect:'none',touchAction:'none'}:{})} as object}>
   <View pointerEvents="none" importantForAccessibility="no-hide-descendants" aria-hidden style={{position:'absolute',inset:0}}>
    <LinePiece from={{x:22,y:height-22}} to={{x:width-22,y:22}} className={joinClasses(!unstyled&&'bg-border')}/>
    {samples.slice(1).map((point,i)=><LinePiece key={i} from={samples[i]!} to={point} className={joinClasses(!unstyled&&'bg-primary')}/>)}
    {shown.points.map(p=><View key={p.id} {...{className:joinClasses(!unstyled&&(p.id===selectedId?'bg-primary border-text':'bg-surface-raised border-primary'))}} style={{position:'absolute',left:22+p.x*w-6,top:22+(1-p.y)*h-6,width:12,height:12,borderRadius:6,borderWidth:2}}/>)}
   </View>
  </View></Transport>
  <View style={{flexDirection:'row',flexWrap:'wrap',gap:8}}><UnitInput label="Curve input" value={selected.x} min={0} max={1} step={.01} precision={6} disabled={disabled||!canRemove} unstyled={unstyled} onCommit={x=>commitPoint(x,selected.y)}/><UnitInput label="Curve output" value={selected.y} min={0} max={1} step={.01} precision={6} disabled={disabled} unstyled={unstyled} onCommit={y=>commitPoint(selected.x,y)}/></View>
  <View style={{flexDirection:'row',flexWrap:'wrap',gap:8}}><Button title="Add curve point" disabled={disabled||value.points.length>=64} unstyled={unstyled} onPress={()=>{
   if(disabled||value.points.length>=64)return;let gap=0;for(let i=1;i<value.points.length-1;i++)if(value.points[i+1]!.x-value.points[i]!.x>value.points[gap+1]!.x-value.points[gap]!.x)gap=i;
   const x=(value.points[gap]!.x+value.points[gap+1]!.x)/2,id=createPointId();const next={...value,points:[...value.points.slice(0,gap+1),{id,x,y:evaluateCurve(value,x)},...value.points.slice(gap+1)]};validateCurve(next);onCommit(next,id);
  }}/><Button title="Remove curve point" disabled={disabled||!canRemove} unstyled={unstyled} onPress={()=>{if(!disabled&&canRemove)onCommit({...value,points:value.points.filter(p=>p.id!==selectedId)},value.points[index-1]!.id);}}/></View>
  <Text {...{className:joinClasses(!unstyled&&'text-text-muted')}}>Drag a point; arrows adjust the selected point. Escape cancels. Input runs left to right in every locale.</Text>
 </View>;
}

/**
 * Small pieces shared by the vector-tools components: a straight overlay line
 * drawn as a rotated view (the PatchGraph wire technique, since the package has
 * no SVG dependency), and a command button that stays pressable while
 * unavailable so it can say why in the cluster's notice line.
 */
import {useRef,type ReactNode} from "react";
import {PanResponder,Pressable,Text,View,type GestureResponderEvent} from "react-native";
import {createCanvasResponder} from "@/components/nyc-tron/ui/components/gestures/canvas-responder";
import {joinClasses} from "@/components/nyc-tron/ui/components/styles";
import type {Point} from "@/components/nyc-tron/ui/components/forge/vector/vector-types";

/** Every vector-tools control target is at least this many points square. */
export const VECTOR_TOUCH_TARGET=44;

/** A straight line between two view points, never a touch target. */
export function LinePiece({from,to,thickness=2,className,color,opacity=1}:{
  from:Point;to:Point;thickness?:number;className?:string|undefined;color?:string|undefined;opacity?:number;
}){
  const dx=to.x-from.x,dy=to.y-from.y,len=Math.hypot(dx,dy);
  if(len<0.01)return null;
  return <View pointerEvents="none" {...{className}}
    style={{position:"absolute",left:(from.x+to.x-len)/2,top:(from.y+to.y)/2-thickness/2,width:len,height:thickness,
      opacity,...(color?{backgroundColor:color}:null),transform:[{rotate:Math.atan2(dy,dx)*180/Math.PI+"deg"}]}}/>;
}

/**
 * Command button for the vector tools. When `reason` is set the button reads
 * as unavailable but still takes the press and reports the reason instead of
 * running, so nothing is silently dead.
 */
export function VectorButton({label,reason,onPress,onBlocked,role="button",checked,styled,children,testID}:{
  label:string;reason?:string|undefined;onPress:()=>void;onBlocked:(reason:string)=>void;
  role?:"button"|"radio"|"switch";checked?:boolean;styled:boolean;children?:ReactNode;testID?:string;
}){
  const disabled=reason!==undefined;
  const on=checked===true;
  // React Native Web's Pressable overwrites aria-disabled with its own
  // `disabled` prop, which would swallow the press; "unavailable" in the name
  // carries the state on web and accessibilityState carries it natively.
  return <Pressable role={role} aria-label={disabled?label+", unavailable":label} testID={testID}
    aria-checked={role==="button"?undefined:on} accessibilityState={{disabled,...(role==="button"?{}:{checked:on})}}
    accessibilityHint={reason}
    onPress={()=>{if(reason!==undefined)onBlocked(reason);else onPress();}}
    {...{className:joinClasses(styled&&"rounded-control border focus-visible:ring-2 focus-visible:ring-focus",
      styled&&(on?"border-primary bg-primary":"border-border bg-surface-raised"))}}
    style={{minWidth:VECTOR_TOUCH_TARGET,minHeight:VECTOR_TOUCH_TARGET,paddingHorizontal:12,
      flexDirection:"row",alignItems:"center",justifyContent:"center",gap:6,opacity:disabled?0.5:1}}>
    {children}
    <Text numberOfLines={1} {...{className:joinClasses(styled&&(on?"text-on-primary":"text-text"))}}
      style={{fontSize:13,fontWeight:on?"700":"500"}}>{label}</Text>
  </Pressable>;
}

/** Polite status line: hints, and the reason an unavailable command did not run. */
export function NoticeLine({text,styled,testID}:{text:string|undefined;styled:boolean;testID?:string}){
  return <Text accessibilityLiveRegion="polite" aria-live="polite" testID={testID}
    {...{className:joinClasses(styled&&"text-text-muted text-xs")}} style={{minHeight:18}}>{text??""}</Text>;
}

/** Group heading inside an inspector or bar. */
export function GroupLabel({children,styled,nativeID}:{children:string;styled:boolean;nativeID?:string}){
  return <Text accessibilityRole="header" nativeID={nativeID}
    {...{className:joinClasses(styled&&"text-text text-xs font-semibold")}}>{children}</Text>;
}

/** Modifier keys seen during a canvas drag. React Native Web reports Shift; Alt comes from key tracking. */
export interface DragModifiers {
  readonly alt:boolean;
  readonly shift:boolean;
  readonly ctrl?:boolean;
  readonly meta?:boolean;
}
/** Keyboard event shape on web (`key`, modifiers) and native (`nativeEvent`). */
export type CanvasKeyEvent={
  key?:string;shiftKey?:boolean;altKey?:boolean;preventDefault?:()=>void;
  nativeEvent?:{key?:string;shiftKey?:boolean;altKey?:boolean};
};
/** Props for {@linkcode CanvasKnob}. */
export interface CanvasKnobProps {
  /** Centre in overlay points. */
  at:Point;
  testID:string;
  label:string;
  hint:string;
  selected:boolean;
  actions:readonly {name:string;label:string}[];
  onAction:(name:string)=>void;
  onKeyDown:(event:CanvasKeyEvent)=>void;
  onFocus?:()=>void;
  onBegin:(modifiers:DragModifiers)=>void;
  /** View-space travel since the press. Preview only. */
  onMove:(dx:number,dy:number,modifiers:DragModifiers)=>void;
  onRelease:()=>void;
  onCancel:()=>void;
  /** Drawn marker, centred in the 44pt target. */
  children:ReactNode;
  zIndex?:number;
  styled:boolean;
}
/**
 * A 44pt draggable, focusable target centred on an on-canvas point. A second
 * pointer or OS termination cancels; a parent scroll view cannot steal it.
 */
export function CanvasKnob(props:CanvasKnobProps){
  const {at,testID,label,hint,selected,actions,onAction,onKeyDown,onFocus,children,zIndex=1,styled}=props;
  const latest=useRef(props);
  latest.current=props;
  const pan=useRef<ReturnType<typeof PanResponder.create>|null>(null);
  if(!pan.current)pan.current=createCanvasResponder({
    onStartShouldSetPanResponder:e=>(e.nativeEvent.touches?.length??1)<=1,
    onMoveShouldSetPanResponder:()=>true,
    onPanResponderGrant:e=>{const n=e.nativeEvent as {altKey?:boolean;shiftKey?:boolean;ctrlKey?:boolean;metaKey?:boolean};latest.current.onBegin({alt:n.altKey===true,shift:n.shiftKey===true,ctrl:n.ctrlKey===true,meta:n.metaKey===true});},
    onPanResponderMove:(e:GestureResponderEvent,g)=>{
      if(g.numberActiveTouches>1){latest.current.onCancel();return;}
      const n=e.nativeEvent as {altKey?:boolean;shiftKey?:boolean};
      latest.current.onMove(g.dx,g.dy,{alt:n.altKey===true,shift:n.shiftKey===true});
    },
    onPanResponderRelease:()=>latest.current.onRelease(),
    onPanResponderTerminationRequest:()=>false,
    onPanResponderTerminate:()=>latest.current.onCancel(),
  });
  return <View {...pan.current.panHandlers} accessible testID={testID}
    accessibilityRole="button" accessibilityLabel={label} accessibilityHint={hint}
    accessibilityState={{selected}} accessibilityActions={actions}
    onAccessibilityAction={e=>onAction(e.nativeEvent.actionName)}
    {...{onKeyDown,focusable:true,onFocus,
      className:joinClasses(styled&&"rounded-control focus-visible:ring-2 focus-visible:ring-focus")}}
    style={{position:"absolute",left:at.x-VECTOR_TOUCH_TARGET/2,top:at.y-VECTOR_TOUCH_TARGET/2,
      width:VECTOR_TOUCH_TARGET,height:VECTOR_TOUCH_TARGET,alignItems:"center",justifyContent:"center",zIndex}}>
    {children}
  </View>;
}

import {PanResponder,Platform,type GestureResponderEvent,type PanResponderCallbacks,type PanResponderGestureState} from "react-native";

type Pointer = {
  pointerId:number;button:number;isPrimary?:boolean;clientX:number;clientY:number;pageX:number;pageY:number;
  altKey?:boolean;shiftKey?:boolean;ctrlKey?:boolean;metaKey?:boolean;
};
type Surface = {
  focus?(options?:{preventScroll?:boolean}):void;
  getBoundingClientRect():{left:number;top:number};
  setPointerCapture(id:number):void;
  releasePointerCapture(id:number):void;
  hasPointerCapture(id:number):boolean;
};
type PointerEvent = {
  nativeEvent:Pointer;currentTarget:Surface;
  preventDefault():void;
};

/**
 * Canvas gesture transport. Native keeps PanResponder. Web uses actual pointer
 * capture because RN Web deliberately excludes Alt/Ctrl mouse presses from its
 * responder system, while canvas tools need those modifiers for editing.
 * Pointer positions are normalized to the same local/page coordinate contract.
 */
export function createCanvasResponder(config:PanResponderCallbacks):ReturnType<typeof PanResponder.create>{
  if(Platform.OS!=="web")return PanResponder.create(config);
  let active:{id:number;surface:Surface;x:number;y:number;pageX:number;pageY:number}|undefined;
  const normalize=(event:PointerEvent):[GestureResponderEvent,PanResponderGestureState]=>{
    const n=event.nativeEvent,rect=event.currentTarget.getBoundingClientRect();
    const start=active??{x:n.clientX,y:n.clientY,pageX:n.pageX,pageY:n.pageY};
    const nativeEvent={...n,locationX:n.clientX-rect.left,locationY:n.clientY-rect.top,
      altKey:n.altKey,shiftKey:n.shiftKey,ctrlKey:n.ctrlKey,metaKey:n.metaKey,
      pageX:n.pageX,pageY:n.pageY,touches:[{pageX:n.pageX,pageY:n.pageY}]};
    const gesture={stateID:n.pointerId,moveX:n.pageX,moveY:n.pageY,x0:start.pageX,y0:start.pageY,
      dx:n.clientX-start.x,dy:n.clientY-start.y,vx:0,vy:0,numberActiveTouches:1};
    // These are event/coordinate adapters only; no native resource is fabricated.
    return [{nativeEvent,preventDefault:()=>event.preventDefault()} as unknown as GestureResponderEvent,gesture as PanResponderGestureState];
  };
  const release=()=>{
    const owner=active;active=undefined;
    if(owner?.surface.hasPointerCapture(owner.id))owner.surface.releasePointerCapture(owner.id);
  };
  const handlers={
    onPointerDown(event:PointerEvent){
      const n=event.nativeEvent;
      if(active){const args=normalize(event);args[1].numberActiveTouches=2;try{config.onPanResponderTerminate?.(...args);}finally{release();}return;}
      if(n.button!==0||n.isPrimary===false)return;
      const args=normalize(event);
      if(config.onStartShouldSetPanResponder?.(...args)===false)return;
      event.preventDefault();
      event.currentTarget.focus?.({preventScroll:true});
      active={id:n.pointerId,surface:event.currentTarget,x:n.clientX,y:n.clientY,pageX:n.pageX,pageY:n.pageY};
      event.currentTarget.setPointerCapture(n.pointerId);
      config.onPanResponderGrant?.(...normalize(event));
    },
    onPointerMove(event:PointerEvent){if(active?.id===event.nativeEvent.pointerId)config.onPanResponderMove?.(...normalize(event));},
    onPointerUp(event:PointerEvent){
      if(active?.id!==event.nativeEvent.pointerId)return;
      try{config.onPanResponderRelease?.(...normalize(event));}finally{release();}
    },
    onPointerCancel(event:PointerEvent){
      if(active?.id!==event.nativeEvent.pointerId)return;
      try{config.onPanResponderTerminate?.(...normalize(event));}finally{release();}
    },
    onLostPointerCapture(event:PointerEvent){
      if(active?.id!==event.nativeEvent.pointerId)return;
      try{config.onPanResponderTerminate?.(...normalize(event));}finally{release();}
    },
  };
  return {panHandlers:handlers as unknown as ReturnType<typeof PanResponder.create>["panHandlers"],getInteractionHandle:()=>undefined};
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}
